import difflib,hashlib,json,re
from pathlib import Path
p=Path(__file__).parent;symbols=json.loads((p/'symbols.json').read_text());records={}
for kind,pattern in {'divide':'integer_op<','widen':'try_numeric_cast<','decimal':'integer_decimal_buffer::'}.items():
 normal={};info={}
 for variant,rows in symbols.items():
  row=next(r for r in rows if pattern in r['name'])
  instructions=[]
  for line in (p/f'{variant}-{kind}.asm').read_text().splitlines():
   m=re.match(r'^\s*([0-9a-f]+):\s*(.*)',line)
   if not m:continue
   offset=int(m[1],16)-row['address'];text=re.split(r'\s+#\s+',m[2],maxsplit=1)[0]
   text=re.sub(r'-?0x[0-9a-f]+\(%rip\)','RIP_DISPLACEMENT(%rip)',text)
   branch=re.match(r'^(j\w+|call)\s+([0-9a-f]+)\s+<(.*)>$',text)
   if branch:
    target=int(branch[2],16)
    text=branch[1]+' '+(f'LOCAL_{target-row["address"]:x}' if row['address']<=target<row['address']+row['size'] else branch[3])
   text=' '.join(text.split());instructions.append(f'{offset:x}: {text}')
  normalized='\n'.join(instructions)+'\n';normal[variant]=normalized;info[variant]={'address':hex(row['address']),'size_bytes':row['size'],'instruction_count':len(instructions),'normalized_sha256':hashlib.sha256(normalized.encode()).hexdigest()};(p/f'{variant}-{kind}-normalized.txt').write_text(normalized)
 records[kind]={'symbols':info,'normalized_equal':normal['before']==normal['after'],'diff':''.join(difflib.unified_diff(normal['before'].splitlines(True),normal['after'].splitlines(True),fromfile='before',tofile='after'))}
 print(kind,records[kind]['normalized_equal'],info)
(p/'assembly-comparison.json').write_text(json.dumps({'method':'objdump instruction offsets and operands with branch targets made relative within the function, external direct calls named, RIP displacements/comments omitted. Relocation-insensitive shape comparison, not a byte-identical binary or microarchitectural equivalence claim.','functions':records},indent=2)+'\n')
